<script setup lang="ts">
type ContentRow = { id: string; type: string; title: string; slug: string; part?: number; level?: number; status: string; currentVersion: number; updatedAt: string };
type AdminUser = { id: string; email: string; displayName: string; status: 'ACTIVE' | 'SUSPENDED' | 'DELETED'; createdAt: string; roles: string[]; plan: string };
type AuditEntry = { id: string; action: string; entity: string; entityId?: string | null; createdAt: string; actor?: { email: string; displayName: string } | null };
type OperationsOverview = { users: Record<string, number>; content: Record<string, number>; media: Record<string, number>; imports: Record<string, number>; writing: Record<string, number>; reports: Record<string, number>; orders: Record<string, number>; recentAudit: AuditEntry[] };
const { request, accessToken } = useAppApi();
const tab = ref<'content' | 'import' | 'media' | 'users' | 'audit'>('content');
const search = ref(''); const typeFilter = ref('ALL'); const loading = ref(false); const saving = ref(false); const notice = ref('');
const rows = ref<ContentRow[]>([{ id: 'demo-1', type: 'LISTENING', title: 'Part 1 · Tranh cảnh vật', slug: 'part-1-tranh-canh-vat', part: 1, level: 1, status: 'PUBLISHED', currentVersion: 1, updatedAt: '2026-09-06' }, { id: 'demo-2', type: 'VOCABULARY', title: '600 từ TOEIC · Workplace', slug: '600-tu-toeic-workplace', level: 2, status: 'DRAFT', currentVersion: 1, updatedAt: '2026-09-05' }]);
const draftTitle = ref(''); const draftSlug = ref(''); const draftType = ref('LISTENING'); const draftPayload = ref('{\n  "content": ""\n}');
const importText = ref('[\n  { "externalKey": "listen-001", "type": "LISTENING", "title": "Office scene", "payload": { "audio": "office.mp3" } }\n]'); const importResult = ref<{ valid: boolean; errors?: Array<{ rowNumber: number; field: string; message: string }>; normalized?: unknown[] } | null>(null);
const selectedFile = ref<File | null>(null); const uploadMessage = ref('');
const overview = ref<OperationsOverview | null>(null); const adminUsers = ref<AdminUser[]>([]); const auditEntries = ref<AuditEntry[]>([]); const userSearch = ref(''); const operationsLoading = ref(false);
const filteredRows = computed(() => rows.value.filter((row) => (typeFilter.value === 'ALL' || row.type === typeFilter.value) && (!search.value.trim() || `${row.title} ${row.slug}`.toLowerCase().includes(search.value.toLowerCase()))));
const activeUsers = computed(() => overview.value?.users.ACTIVE ?? adminUsers.value.filter((user) => user.status === 'ACTIVE').length);
const pendingReviews = computed(() => (overview.value?.writing.PENDING ?? 0) + (overview.value?.reports.OPEN ?? 0));

async function loadOperations() {
  if (!accessToken.value) return;
  operationsLoading.value = true;
  try {
    const [nextOverview, users, audit] = await Promise.all([
      request<OperationsOverview>('/admin/overview'),
      request<AdminUser[]>('/admin/users', { query: { search: userSearch.value, limit: 100 } }),
      request<AuditEntry[]>('/admin/audit', { query: { limit: 24 } })
    ]);
    overview.value = nextOverview; adminUsers.value = users; auditEntries.value = audit;
  } catch {
    notice.value = 'Không tải được vận hành live. Hãy đăng nhập bằng tài khoản admin hoặc kiểm tra quyền.';
  } finally { operationsLoading.value = false; }
}

async function loadContent() {
  if (!accessToken.value) return;
  loading.value = true;
  try { const live = await request<ContentRow[]>('/admin/content', { query: { page: 1, pageSize: 100 } }); if (live.length) rows.value = live; }
  catch { notice.value = 'Không tải được content live; đang hiển thị bản xem trước.'; }
  finally { loading.value = false; }
}

onMounted(async () => { await Promise.all([loadContent(), loadOperations()]); });

async function createDraft() {
  if (!draftTitle.value.trim() || !draftSlug.value.trim()) return;
  let payload: Record<string, unknown>; try { payload = JSON.parse(draftPayload.value); } catch { notice.value = 'Payload phải là JSON object hợp lệ.'; return; }
  saving.value = true; notice.value = '';
  try {
    if (accessToken.value) { const created = await request<ContentRow>('/admin/content', { method: 'POST', body: { type: draftType.value, title: draftTitle.value, slug: draftSlug.value, payload } }); rows.value.unshift(created); }
    else rows.value.unshift({ id: `demo-${Date.now()}`, type: draftType.value, title: draftTitle.value, slug: draftSlug.value, status: 'DRAFT', currentVersion: 1, updatedAt: 'vừa xong' });
    notice.value = 'Đã tạo content draft.'; draftTitle.value = ''; draftSlug.value = '';
  } catch { notice.value = 'Chưa tạo được draft. Kiểm tra quyền content editor.'; } finally { saving.value = false; }
}

async function publish(row: ContentRow) { try { if (accessToken.value && !row.id.startsWith('demo-')) await request(`/admin/content/${row.id}/publish`, { method: 'POST' }); row.status = 'PUBLISHED'; notice.value = `Đã publish “${row.title}”.`; } catch { notice.value = 'Publish thất bại. Kiểm tra role và phiên đăng nhập.'; } }
async function runImport() { try { const rowsToImport = JSON.parse(importText.value); if (!Array.isArray(rowsToImport)) throw new Error('not array'); if (accessToken.value) importResult.value = await request('/admin/imports', { method: 'POST', body: { sourceName: 'admin-console.json', schema: 'content-v1', rows: rowsToImport } }); else importResult.value = { valid: rowsToImport.every((row) => row.externalKey && row.type && row.title && row.payload && typeof row.payload === 'object'), normalized: rowsToImport }; } catch { importResult.value = { valid: false, errors: [{ rowNumber: 0, field: 'json', message: 'JSON phải là một array hợp lệ.' }] }; } }
function chooseFile(event: Event) { selectedFile.value = (event.target as HTMLInputElement).files?.[0] ?? null; uploadMessage.value = ''; }
async function uploadFile() { if (!selectedFile.value) return; if (!accessToken.value) { uploadMessage.value = 'Đã chọn file. Đăng nhập admin để upload vào storage.'; return; } try { const file = selectedFile.value; const session = await request<{ sessionId: string; mode: string; method: string; url: string; headers: Record<string, string> }>('/media/upload-sessions', { method: 'POST', body: { originalName: file.name, mimeType: file.type, byteSize: file.size, purpose: 'admin-content' } }); if (session.mode === 'direct') await $fetch(session.url, { method: session.method as 'PUT', body: file, headers: session.headers }); else { const form = new FormData(); form.append('file', file); await request(`/media/upload-sessions/${session.sessionId}/file`, { method: 'POST', body: form }); } if (session.mode === 'direct') await request(`/media/upload-sessions/${session.sessionId}/complete`, { method: 'POST' }); uploadMessage.value = 'Upload thành công và asset đã sẵn sàng.'; } catch { uploadMessage.value = 'Upload thất bại. Kiểm tra provider, MIME type hoặc quyền admin.'; } }
async function updateUserStatus(user: AdminUser, status: AdminUser['status']) {
  if (!accessToken.value || user.status === status) return;
  try {
    const updated = await request<Pick<AdminUser, 'id' | 'status'>>(`/admin/users/${user.id}/status`, { method: 'PATCH', body: { status } });
    adminUsers.value = adminUsers.value.map((item) => item.id === updated.id ? { ...item, status: updated.status } : item);
    notice.value = `Đã cập nhật trạng thái của ${user.displayName}.`;
    await loadOperations();
  } catch { notice.value = 'Không cập nhật được trạng thái. Kiểm tra quyền hoặc thử lại.'; }
}
</script>

<template>
  <div class="page-enter space-y-6"><section class="rounded-[26px] bg-ink p-6 text-white shadow-float sm:p-9"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-extrabold tracking-[0.18em] text-bean">ADMIN CONSOLE</p><h1 class="mt-3 text-4xl font-extrabold tracking-[-0.06em] sm:text-5xl">Vận hành rõ ràng.</h1><p class="mt-3 max-w-xl text-sm leading-6 text-white/65">Quản lý content, người dùng, import, media và các tín hiệu hệ thống từ một nơi có thể kiểm soát.</p></div><div class="rounded-2xl bg-white/10 px-4 py-3 text-right"><p class="text-[11px] text-white/55">Health</p><p class="mt-1 text-xl font-extrabold text-leaf">● Online</p></div></div></section><div class="flex gap-1 overflow-x-auto rounded-2xl border border-line bg-white p-1 shadow-soft" role="tablist" aria-label="Admin modules"><button v-for="item in [{ key: 'content', label: 'Content' }, { key: 'users', label: 'Người dùng' }, { key: 'import', label: 'Import' }, { key: 'media', label: 'Media' }, { key: 'audit', label: 'Audit & health' }]" :key="item.key" :class="['shrink-0 rounded-xl px-4 py-3 text-xs font-extrabold transition focus-ring', tab === item.key ? 'bg-ink text-white' : 'text-ink/55 hover:bg-paper']" @click="tab = item.key as typeof tab">{{ item.label }}</button></div><p v-if="notice" class="rounded-xl bg-bean/20 p-3 text-xs font-bold text-[#8B6400]">{{ notice }}</p>

    <section v-if="tab === 'content'" class="space-y-5"><div class="grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-6"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-extrabold text-ink/45">CONTENT LIBRARY</p><h2 class="mt-1 text-xl font-extrabold">{{ filteredRows.length }} items</h2></div><span v-if="loading" class="text-xs text-ink/45">Đang tải...</span></div><div class="mt-5 flex flex-wrap gap-2"><input v-model="search" class="min-w-[180px] flex-1 rounded-xl border border-line bg-paper px-3 py-2.5 text-xs outline-none focus:border-iris" placeholder="Tìm title hoặc slug..." aria-label="Tìm content"><select v-model="typeFilter" class="rounded-xl border border-line bg-paper px-3 py-2.5 text-xs font-bold outline-none focus:border-iris" aria-label="Lọc loại content"><option>ALL</option><option>LISTENING</option><option>READING</option><option>GRAMMAR</option><option>VOCABULARY</option><option>EXAM</option><option>VIDEO</option><option>WRITING</option></select></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[640px] text-left text-xs"><thead class="text-ink/40"><tr><th class="pb-3 pr-4 font-bold">Content</th><th class="pb-3 pr-4 font-bold">Type</th><th class="pb-3 pr-4 font-bold">Status</th><th class="pb-3 font-bold">Action</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id" class="border-t border-line"><td class="py-3 pr-4"><p class="font-extrabold">{{ row.title }}</p><p class="mt-1 text-ink/40">{{ row.slug }} · v{{ row.currentVersion }}</p></td><td class="py-3 pr-4 font-bold text-iris">{{ row.type }}</td><td class="py-3 pr-4"><span :class="['rounded-lg px-2 py-1 text-[10px] font-extrabold', row.status === 'PUBLISHED' ? 'bg-leaf/15 text-[#28896D]' : 'bg-bean/20 text-[#A87400]']">{{ row.status }}</span></td><td class="py-3"><button v-if="row.status !== 'PUBLISHED'" class="rounded-lg px-2 py-1 font-bold text-iris hover:bg-iris/10 focus-ring" @click="publish(row)">Publish</button><span v-else class="text-ink/35">Live</span></td></tr></tbody></table></div></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-6"><p class="text-xs font-extrabold text-ink/45">CREATE DRAFT</p><h2 class="mt-1 text-xl font-extrabold">Thêm một bài mới</h2><div class="mt-5 space-y-3"><input v-model="draftTitle" class="w-full rounded-xl border border-line bg-paper px-3 py-3 text-sm outline-none focus:border-iris" placeholder="Title"><input v-model="draftSlug" class="w-full rounded-xl border border-line bg-paper px-3 py-3 text-sm outline-none focus:border-iris" placeholder="slug-noi-dung"><select v-model="draftType" class="w-full rounded-xl border border-line bg-paper px-3 py-3 text-sm outline-none focus:border-iris"><option>LISTENING</option><option>READING</option><option>GRAMMAR</option><option>VOCABULARY</option><option>EXAM</option><option>VIDEO</option><option>WRITING</option></select><textarea v-model="draftPayload" rows="7" class="w-full rounded-xl border border-line bg-paper px-3 py-3 font-mono text-xs outline-none focus:border-iris" aria-label="Payload JSON" /><button class="w-full rounded-xl bg-ink px-4 py-3 text-xs font-extrabold text-white transition hover:bg-iris disabled:opacity-40 focus-ring" :disabled="saving || !draftTitle.trim() || !draftSlug.trim()" @click="createDraft">{{ saving ? 'Đang tạo...' : 'Tạo draft' }}</button></div></div></div></section>

    <section v-else-if="tab === 'users'" class="space-y-5"><div class="grid gap-4 sm:grid-cols-3"><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft"><p class="text-xs font-extrabold text-ink/45">ACTIVE LEARNERS</p><p class="mt-3 text-3xl font-extrabold tracking-[-0.06em]">{{ activeUsers }}</p><p class="mt-1 text-xs text-ink/50">Tài khoản đang hoạt động</p></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft"><p class="text-xs font-extrabold text-ink/45">PENDING REVIEW</p><p class="mt-3 text-3xl font-extrabold tracking-[-0.06em]">{{ pendingReviews }}</p><p class="mt-1 text-xs text-ink/50">Writing và report cần xử lý</p></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft"><p class="text-xs font-extrabold text-ink/45">AUDIT EVENTS</p><p class="mt-3 text-3xl font-extrabold tracking-[-0.06em]">{{ overview?.recentAudit.length ?? 0 }}</p><p class="mt-1 text-xs text-ink/50">Sự kiện gần nhất đã ghi nhận</p></div></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-6"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-extrabold text-ink/45">ACCESS REVIEW</p><h2 class="mt-1 text-xl font-extrabold">Quyền và trạng thái người dùng</h2></div><button class="rounded-xl border border-line px-3 py-2 text-xs font-extrabold hover:bg-paper focus-ring" :disabled="operationsLoading" @click="loadOperations">{{ operationsLoading ? 'Đang tải...' : 'Làm mới' }}</button></div><div class="mt-5 flex flex-wrap gap-2"><input v-model="userSearch" class="min-w-[180px] flex-1 rounded-xl border border-line bg-paper px-3 py-2.5 text-xs outline-none focus:border-iris" placeholder="Tìm tên hoặc email..." aria-label="Tìm người dùng" @keyup.enter="loadOperations"><button class="rounded-xl bg-ink px-4 py-2.5 text-xs font-extrabold text-white hover:bg-iris focus-ring" @click="loadOperations">Tìm</button></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[760px] text-left text-xs"><thead class="text-ink/40"><tr><th class="pb-3 pr-4 font-bold">Người dùng</th><th class="pb-3 pr-4 font-bold">Vai trò</th><th class="pb-3 pr-4 font-bold">Gói</th><th class="pb-3 pr-4 font-bold">Trạng thái</th><th class="pb-3 font-bold">Thao tác</th></tr></thead><tbody><tr v-for="user in adminUsers" :key="user.id" class="border-t border-line"><td class="py-3 pr-4"><p class="font-extrabold">{{ user.displayName }}</p><p class="mt-1 text-ink/40">{{ user.email }}</p></td><td class="py-3 pr-4"><span class="rounded-lg bg-iris/10 px-2 py-1 text-[10px] font-extrabold text-iris">{{ user.roles.join(' · ') || 'LEARNER' }}</span></td><td class="py-3 pr-4 font-bold">{{ user.plan }}</td><td class="py-3 pr-4"><span :class="['rounded-lg px-2 py-1 text-[10px] font-extrabold', user.status === 'ACTIVE' ? 'bg-leaf/15 text-[#28896D]' : 'bg-[#FFE6E2] text-[#B5473A]']">{{ user.status }}</span></td><td class="py-3"><button v-if="user.status === 'ACTIVE'" class="rounded-lg px-2 py-1 font-bold text-[#B5473A] hover:bg-[#FFE6E2] focus-ring" @click="updateUserStatus(user, 'SUSPENDED')">Tạm khóa</button><button v-else class="rounded-lg px-2 py-1 font-bold text-iris hover:bg-iris/10 focus-ring" @click="updateUserStatus(user, 'ACTIVE')">Kích hoạt</button></td></tr><tr v-if="!operationsLoading && !adminUsers.length"><td colspan="5" class="py-8 text-center text-ink/45">Chưa có dữ liệu hoặc bạn chưa có quyền admin.</td></tr></tbody></table></div></div></section>

    <section v-else-if="tab === 'import'" class="grid gap-5 lg:grid-cols-[1fr_.8fr]"><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-7"><p class="text-xs font-extrabold text-ink/45">BATCH IMPORT</p><h2 class="mt-1 text-xl font-extrabold">Import content JSON</h2><p class="mt-2 text-xs leading-5 text-ink/55">Mỗi row cần externalKey, type, title và payload object. API sẽ trả lỗi theo từng row.</p><textarea v-model="importText" rows="16" class="mt-5 w-full rounded-2xl border border-line bg-paper px-4 py-3 font-mono text-xs leading-6 outline-none focus:border-iris" aria-label="Import JSON" /><button class="mt-4 rounded-xl bg-ink px-5 py-3 text-xs font-extrabold text-white transition hover:bg-iris focus-ring" @click="runImport">Validate & import</button></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-7"><p class="text-xs font-extrabold text-ink/45">VALIDATION RESULT</p><div v-if="importResult" class="mt-5 rounded-2xl p-4" :class="importResult.valid ? 'bg-leaf/10' : 'bg-[#FFE6E2]'"><p class="text-sm font-extrabold">{{ importResult.valid ? 'Batch hợp lệ' : 'Batch có lỗi' }}</p><p class="mt-2 text-xs text-ink/60">{{ importResult.normalized?.length ?? 0 }} row đã normalize · {{ importResult.errors?.length ?? 0 }} lỗi</p><ul v-if="importResult.errors?.length" class="mt-4 space-y-2 text-xs text-[#B5473A]"><li v-for="error in importResult.errors" :key="`${error.rowNumber}-${error.field}`">Row {{ error.rowNumber }} · {{ error.field }}: {{ error.message }}</li></ul></div><div v-else class="mt-5 rounded-2xl bg-paper p-4 text-xs leading-6 text-ink/55">Chưa có kết quả. Validate trước khi import để tránh batch lỗi đi vào kho content.</div></div></section>

    <section v-else-if="tab === 'media'" class="mx-auto max-w-2xl rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-7"><p class="text-xs font-extrabold text-ink/45">MEDIA INGESTION</p><h2 class="mt-1 text-xl font-extrabold">Upload asset an toàn</h2><p class="mt-2 text-xs leading-5 text-ink/55">Frontend dùng upload session. Backend tự chọn local, AWS S3 hoặc Cloudflare R2 theo cấu hình server.</p><label class="mt-6 flex cursor-pointer flex-col items-center rounded-2xl border-2 border-dashed border-line bg-paper p-8 text-center hover:border-iris"><span class="text-3xl text-iris">↥</span><span class="mt-3 text-sm font-extrabold">Chọn audio, video, ảnh hoặc PDF</span><span class="mt-1 text-xs text-ink/45">Tối đa 500MB · MIME được allowlist</span><input class="sr-only" type="file" accept="audio/*,video/mp4,image/*,application/pdf,text/plain" @change="chooseFile"></label><p v-if="selectedFile" class="mt-4 rounded-xl bg-paper p-3 text-xs font-bold">{{ selectedFile.name }} · {{ Math.ceil(selectedFile.size / 1024) }}KB</p><button class="mt-4 w-full rounded-xl bg-ink px-4 py-3 text-xs font-extrabold text-white transition hover:bg-iris disabled:opacity-40 focus-ring" :disabled="!selectedFile" @click="uploadFile">Upload asset</button><p v-if="uploadMessage" class="mt-4 text-xs font-bold text-ink/60">{{ uploadMessage }}</p></section>

    <section v-else class="space-y-5"><div class="grid gap-5 md:grid-cols-3"><div v-for="item in [{ label: 'API health', value: 'Online', detail: 'NestJS · /api/v1/health', tone: 'text-leaf' }, { label: 'Content live', value: `${overview?.content.PUBLISHED ?? 0} published`, detail: `${overview?.content.DRAFT ?? 0} draft cần hoàn thiện`, tone: 'text-iris' }, { label: 'Storage', value: 'Configured', detail: `${overview?.media.READY ?? 0} asset ready · provider được chọn server-side`, tone: 'text-[#A87400]' }]" :key="item.label" class="rounded-[22px] border border-line bg-white p-5 shadow-soft"><p class="text-xs font-extrabold text-ink/45">{{ item.label }}</p><p :class="['mt-4 text-2xl font-extrabold', item.tone]">● {{ item.value }}</p><p class="mt-2 text-xs leading-5 text-ink/50">{{ item.detail }}</p></div></div><div class="rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-6"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-extrabold text-ink/45">AUDIT TRAIL</p><h2 class="mt-1 text-xl font-extrabold">Sự kiện vận hành gần đây</h2></div><button class="rounded-xl border border-line px-3 py-2 text-xs font-extrabold hover:bg-paper focus-ring" :disabled="operationsLoading" @click="loadOperations">{{ operationsLoading ? 'Đang tải...' : 'Làm mới' }}</button></div><ol class="mt-5 divide-y divide-line"><li v-for="entry in auditEntries" :key="entry.id" class="flex flex-wrap items-center justify-between gap-2 py-3 text-xs"><div><p class="font-extrabold">{{ entry.action }} <span class="font-normal text-ink/45">· {{ entry.entity }}</span></p><p class="mt-1 text-ink/45">{{ entry.actor?.displayName || entry.actor?.email || 'System' }} · {{ new Date(entry.createdAt).toLocaleString('vi-VN') }}</p></div><span class="rounded-lg bg-paper px-2 py-1 font-bold text-ink/55">{{ entry.entityId ? entry.entityId.slice(0, 8) : 'SYSTEM' }}</span></li><li v-if="!operationsLoading && !auditEntries.length" class="py-8 text-center text-xs text-ink/45">Chưa có sự kiện audit hoặc bạn chưa có quyền admin.</li></ol></div></section>
  </div>
</template>

<style scoped>
